// POST /api/pv — records one page view in public.page_views (plan T16).
//
// The browser used to insert rows into Supabase directly with the public key,
// so anyone could flood the table. Going through this function lets the
// server add what a browser cannot know (country from the CDN edge, a
// server-side bot check), validate and trim every field, and rate-limit per
// IP. No cookies and no personal data are stored: the session id is a random
// per-tab value generated by the page.
//
// Writes with SUPABASE_SERVICE_ROLE_KEY when it is set in Netlify's
// environment (then the public insert policy on page_views can be dropped, see
// supabase/migrations/008); otherwise with the anon key, which the bounded
// insert policy still allows.

// Mirrors the bot list in src/lib/isBot.js (the browser skips these itself, so
// anything that still arrives with such a User-Agent is recorded as a bot).
const BOT_UA = new RegExp(
  [
    'bot\\b', 'crawl', 'spider', 'slurp', 'scrape', 'fetch', 'externalagent',
    'facebookexternalhit', 'preview', 'headless', 'lighthouse', 'pagespeed',
    'gtmetrix', 'phantom', 'puppeteer', 'playwright', 'selenium',
    'python', 'curl', 'wget', 'httpclient', 'java/', 'go-http', 'node-fetch', 'axios',
    'ahrefs', 'semrush', 'dataforseo', 'mj12', 'petalbot', 'bytespider', 'claude/',
  ].join('|'),
  'i'
)

const ALLOWED_ORIGIN = /^https:\/\/([a-z0-9-]+\.)*(vexn\.org|netlify\.app)$/i
const DEVICES = new Set(['mobile', 'tablet', 'desktop'])
const MAX_BODY = 4096
const LIMIT_PER_MINUTE = 120 // per IP, per isolate (best effort)
const BOT_LIMIT_PER_MINUTE = 10

const hits = new Map() // ip -> { count, resetAt }

function allowed(ip, limit) {
  const now = Date.now()
  if (hits.size > 5000) for (const [k, v] of hits) if (v.resetAt < now) hits.delete(k)
  const entry = hits.get(ip)
  if (!entry || entry.resetAt < now) {
    hits.set(ip, { count: 1, resetAt: now + 60_000 })
    return true
  }
  entry.count += 1
  return entry.count <= limit
}

const clip = (value, max) => {
  if (value == null) return null
  const s = String(value).trim().slice(0, max)
  return s === '' ? null : s
}

// Turns the browser's JSON into a row that satisfies the table's insert policy,
// or null when the path is unusable.
export function toRow(body, { ua, country }) {
  const path = clip(body?.path, 300)
  if (!path || !path.startsWith('/')) return null
  const status = Number.parseInt(body?.status_code, 10)
  return {
    path,
    referrer: clip(body?.referrer, 2000),
    session_id: clip(body?.session_id, 64),
    visitor_type: !ua || BOT_UA.test(ua) ? 'bot' : 'browser',
    country: country ? clip(country, 8) : null,
    device: DEVICES.has(body?.device) ? body.device : null,
    utm_source: clip(body?.utm_source, 100),
    utm_medium: clip(body?.utm_medium, 100),
    utm_campaign: clip(body?.utm_campaign, 150),
    status_code: status >= 100 && status <= 599 ? status : null,
  }
}

export default async (request, context) => {
  if (request.method !== 'POST') return new Response(null, { status: 405, headers: { allow: 'POST' } })

  const origin = request.headers.get('origin') || ''
  if (origin && !ALLOWED_ORIGIN.test(origin)) return new Response(null, { status: 403 })

  const ua = request.headers.get('user-agent') || ''
  const ip = context?.ip || request.headers.get('x-nf-client-connection-ip') || 'unknown'
  const isBot = !ua || BOT_UA.test(ua)
  if (!allowed(ip, isBot ? BOT_LIMIT_PER_MINUTE : LIMIT_PER_MINUTE)) return new Response(null, { status: 429 })

  let body
  try {
    const text = await request.text()
    if (text.length > MAX_BODY) return new Response(null, { status: 413 })
    body = JSON.parse(text)
  } catch {
    return new Response(null, { status: 400 })
  }

  const row = toRow(body, { ua, country: context?.geo?.country?.code })
  if (!row) return new Response(null, { status: 400 })

  const supabaseUrl = Netlify.env.get('VITE_SUPABASE_URL')
  const key = Netlify.env.get('SUPABASE_SERVICE_ROLE_KEY') || Netlify.env.get('VITE_SUPABASE_ANON_KEY')
  if (!supabaseUrl || !key) return new Response(null, { status: 204 }) // not configured: drop quietly

  try {
    const res = await fetch(`${supabaseUrl}/rest/v1/page_views`, {
      method: 'POST',
      headers: { apikey: key, Authorization: `Bearer ${key}`, 'content-type': 'application/json', Prefer: 'return=minimal' },
      body: JSON.stringify(row),
      signal: AbortSignal.timeout(3000),
    })
    return new Response(null, { status: res.ok ? 204 : 502 })
  } catch {
    return new Response(null, { status: 502 })
  }
}

export const config = { path: '/api/pv' }
